import java.io.*;

class Counter implements Serializable {
    static int instances = 0;
    transient int cache = 10;
    int value;
    Counter(int v) { value = v; instances++; }
}

public class SaveCounter {
    public static void main(String[] args) throws Exception {
        var bos = new ByteArrayOutputStream();
        try (var out = new ObjectOutputStream(bos)) {
            out.writeObject(new Counter(7));
        }
        Counter.instances = 5;
        try (var in = new ObjectInputStream(
                new ByteArrayInputStream(bos.toByteArray()))) {
            Counter c = (Counter) in.readObject();
            System.out.println(c.value + " " + c.cache + " " + Counter.instances);
        }
    }
}

