    int b = 6;
    Base() { b = 7; }
}

class Item extends Base implements Serializable {
    transient String label = "default";
    int qty = 3;
    Item() { a = 50; b = 60; label = "custom"; qty = 30; }
}

public class Restore {
    public static void main(String[] args) throws Exception {
