        try (var out = new ObjectOutputStream(bos)) {
            out.writeObject(new Item());
        }
        try (var in = new ObjectInputStream(
                new ByteArrayInputStream(bos.toByteArray()))) {
            Item i = (Item) in.readObject();
            System.out.println(i.a + " " + i.b + " " + i.label + " " + i.qty);
        }
    }
}

import java.io.*;

class Account implements Serializable {
    String owner;
    transient String pin;
    Account(String o, String p) { owner = o; pin = p; }

    private void writeObject(ObjectOutputStream out) throws IOException {
        out.defaultWriteObject();
        out.writeObject(new StringBuilder(pin).reverse().toString());
    }

    private void readObject(ObjectInputStream in)
            throws IOException, ClassNotFoundException {
        in.defaultReadObject();
        pin = (String) in.readObject() + "!";
    }
}

public class Vault {
    public static void main(String[] args) throws Exception {
        var bos = new ByteArrayOutputStream();
        try (var out = new ObjectOutputStream(bos)) {
            out.writeObject(new Account("ann", "123"));
        }
        try (var in = new ObjectInputStream(
                new ByteArrayInputStream(bos.toByteArray()))) {
            Account a = (Account) in.readObject();
            System.out.println(a.owner + " " + a.pin);
        }
    }
}

